package com.stockflow.inventory; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="idempotency_record",uniqueConstraints=@UniqueConstraint(columnNames={"company_id","idempotency_key"})) @Getter @NoArgsConstructor public class IdempotencyRecord{@Id private UUID id;@Column(name="company_id",nullable=false)private UUID companyId;@Column(name="idempotency_key",nullable=false)private String key;@Column(name="request_hash",nullable=false,length=64)private String requestHash;@Column(name="response_id",nullable=false)private UUID responseId;@Column(nullable=false)private Instant createdAt;public IdempotencyRecord(UUID c,String k,String h,UUID r){id=UUID.randomUUID();companyId=c;key=k;requestHash=h;responseId=r;createdAt=Instant.now();}}
